/* eslint-disable @typescript-eslint/no-explicit-any */
/* eslint-disable @typescript-eslint/ban-types */
interface OverridableTypeMap {
  props: {};
  defaultComponent: React.ElementType;
  classKey: string;
}

type ClassNameMap<ClassKey extends string = string> = Record<ClassKey, string>;

interface StyledComponentProps<ClassKey extends string = string> {
  classes?: Partial<ClassNameMap<ClassKey>>;
  innerRef?: React.Ref<any>;
}

type OverrideProps<M extends OverridableTypeMap, C extends React.ElementType> = BaseProps<M> &
  Omit<React.ComponentPropsWithRef<C>, keyof CommonProps<M>>;

interface CommonProps<M extends OverridableTypeMap> extends StyledComponentProps<M['classKey']> {
  className?: string;
  style?: React.CSSProperties;
}

type BaseProps<M extends OverridableTypeMap> = M['props'] & CommonProps<M>;

type SvgIconClassKey =
  | 'root'
  | 'colorSecondary'
  | 'colorAction'
  | 'colorDisabled'
  | 'colorError'
  | 'colorPrimary'
  | 'fontSizeInherit'
  | 'fontSizeSmall'
  | 'fontSizeLarge';

interface SvgIconTypeMap<P = {}, D extends React.ElementType = 'svg'> {
  props: P & {
    children?: React.ReactNode;
    color?: 'inherit' | 'primary' | 'secondary' | 'action' | 'disabled' | 'error';
    fontSize?: 'default' | 'inherit' | 'large' | 'medium' | 'small';
    htmlColor?: string;
    shapeRendering?: string;
    titleAccess?: string;
    viewBox?: string;
  };
  defaultComponent: D;
  classKey: SvgIconClassKey;
}

export type SvgIconProps<
  D extends React.ElementType = SvgIconTypeMap['defaultComponent'],
  P = {}
> = OverrideProps<SvgIconTypeMap<P, D>, D>;
